import meta from "./meta.json";

export const UPSTREAM_META = meta;

export const CONFIG_ENV_RAW = "# Portal provisioning configuration.\n# Edit these to point at your own client app / assets. Both provision.sh and\n# provision.ps1 read this file.\n\n# Package + components of the client app to install and wire in.\nPKG=com.immortal.launcher\nHOME_ACTIVITY=com.immortal.launcher/.HomeActivity\nDREAM_SERVICE=com.immortal.launcher/.PhotoDreamService\n\n# Stock Aloha components - FALLBACKS ONLY. On first provision the script detects\n# this device's real stock launcher + screensaver and saves them on the device\n# (/sdcard/immortal_restore.env); --restore uses that snapshot so it's correct on\n# any Portal model. These values (Portal Go / touchscreen Aloha) are used only if\n# no snapshot is found.\nSTOCK_HOME=com.facebook.alohaapps.launcher/com.facebook.aloha.app.home.touch.HomeActivity\nSTOCK_DREAM=com.facebook.alohaapps.launcher/com.facebook.aloha.app.home.touch.HomeDreamService\n# Portal's dock/idle screensaver default (separate from the active component).\nSTOCK_DEFAULT_DREAM=com.facebook.alohaapps.superframe/com.facebook.alohaapps.superframe.SuperframeDream\n\n# Meta's required package verifier (the cert allowlist that blocks on-device installs).\nVERIFIER_PKG=com.facebook.appverifier\n\n# GEN-1 PORTAL+ ONLY. Meta ships a Runtime Resource Overlay (RRO) that re-themes\n# framework resources so the stock package-installer dialog renders white-on-white\n# (blank confirm screen, invisible \"Install\" button in the bottom-right corner).\n# Disabling the overlay restores normal styling, making the on-device installer\n# dialog usable again. Unlike the silent daemon and Shizuku, overlay state is\n# persisted by the framework (/data/system/overlays.xml) and SURVIVES A REBOOT, so\n# a rebooted Gen-1 with the daemon down still has a working stock installer for\n# Aurora/F-Droid/sideloads. Applied immediately via `cmd overlay` (no reboot, so\n# it can't kill the daemon). Skipped automatically on newer Portals (API >= 29),\n# which have a working dialog and don't ship this overlay. Reversible via restore.\nDISABLE_INSTALLER_OVERLAY=true\n# Overlay package(s) to disable, space separated. The framework overlay is the one\n# that breaks the installer dialog; a companion settings overlay\n# (com.facebook.aloha.rro.niu.settings) exists on some builds - only ones actually\n# present on the device are touched.\nINSTALLER_OVERLAY_PKGS=\"com.facebook.aloha.rro.niu.android\"\n\n# Which steps to perform.\n# SET_LAUNCHER replaces the SYSTEM home with our launcher (reversible via\n# --restore). True = full replacement (the goal): our launcher becomes the home.\n# Set false if you'd rather it install as a normal app you open from the stock\n# home and exit via its \"Portal Home\" tile.\nSET_LAUNCHER=true\nSET_SCREENSAVER=true\nDISABLE_VERIFIER=true\n# Meta's camera-based presence detector. The system uses it to decide ambient\n# vs sleep at the screen timeout (someone nearby -> photos, empty room -> sleep)\n# and Immortal cooperates with it, so it stays ENABLED by default. Set true only\n# if you want it off (e.g. no camera use at all); restore re-enables it.\nPRESENCE_PKG=com.facebook.alohaservices.presence\nDISABLE_PRESENCE=false\n\n# Block Meta OS updates so a future OTA can't undo this setup or re-enable the\n# verifier. Reversible - restore re-enables them. Portal is discontinued, so this\n# also forgoes any (unlikely) future security patches.\n# BLANK (default) => ask the user (defaults to YES/block when run interactively;\n# blocks unattended too). Set true/false here to force without asking.\nDISABLE_OTA=\nOTA_PACKAGES=\"com.facebook.aloha.alohaotasetup com.facebook.aloha.otaui\"\n\n# Runtime permissions to pre-grant (space separated). Immortal needs none at\n# runtime (install/delete are install-time perms), so this is empty.\nPERMISSIONS=\"\"\n\n# Apps to pre-install during provisioning, via silent `adb install`. This is the\n# reliable way to add apps on models whose on-device installer dialog is broken\n# (notably the Gen-1 Portal+ on Android 9). It also gives every freshly\n# provisioned Portal a few useful apps out of the box.\n#   PREINSTALL_FDROID - F-Droid apps as \"id\" or \"id:versionCode\". Pin the arm64\n#                       versionCode for multi-ABI apps (e.g. VLC), since Portal is arm64.\n#   PREINSTALL_APKS   - direct APK URLs (your own apps / specific builds).\n# Empty by default - a fresh Portal gets the built-in tiles plus the full App Store\n# to install from (and Aurora/Shizuku on Gen-1). Add space-separated F-Droid IDs to\n# preinstall some, e.g. \"org.videolan.vlc:13070106 io.homeassistant.companion.android.minimal\".\n# Pin the arm64 versionCode for multi-ABI apps (e.g. VLC), since Portal is arm64.\nPREINSTALL_FDROID=\"\"\nPREINSTALL_APKS=\"\"\n\n# Apps to relaunch automatically after a reboot (space-separated package names).\n# Some apps have no boot receiver and stay dead until opened - notably the Music\n# Assistant / Sendspin player, which we want always-available on an always-on Portal.\n# Immortal's boot receiver starts each a few seconds after boot, then hands the screen\n# back to home. Also manageable per device in Immortal Settings > Start on boot.\n# Empty = nothing auto-launched. Apps that aren't installed are simply skipped.\nBOOT_APPS=\"io.music_assistant.client\"\n\n# ---- WiFi fleet management ---------------------------------------------------\n# Enable the in-app Fleet Agent: a foreground service Immortal runs so you can\n# manage this Portal over WiFi - deploy/update apps, push config, browse files,\n# read logcat - from the portal-explorer \"Fleet\" view, WITHOUT a USB cable each\n# time. Because it's an app service it SURVIVES A REBOOT (unlike adb-over-WiFi on\n# these non-root Portals). Provisioning names + enables the agent and records this\n# device (name, IP, agent token) to a host-side inventory under fleet/.\n#\n# We deliberately do NOT switch the Portal into raw adb-over-WiFi during\n# provisioning: `adb tcpip` restarts adbd, which would stop Shizuku and the\n# silent-install daemon, and it doesn't survive a reboot anyway. The agent covers\n# day-to-day management; for an occasional raw adb shell / scrcpy, run\n# `./provision.sh --wifi-adb` on demand.\n# Default OFF: the agent is an always-on WiFi management service most single-device\n# users don't need. Enable per device on demand with `./provision.sh --fleet`.\nENABLE_FLEET=false\n# Friendly name for THIS device in the fleet dashboard. Blank = prompt when run\n# interactively, else fall back to the model. Set per device, e.g.\n# FLEET_NAME=\"Living Room Left\".\nFLEET_NAME=\nFLEET_AGENT_PORT=8723\n\n# Relative paths (to this folder).\n#   APK_GLOB   - the client APK to install (first match used)\n#   ASSET_DIR  - any .jpg here is pushed to the app's files dir; the first is named frame.jpg\nAPK_GLOB=apks/*.apk\nASSET_DIR=assets\n\n# Signed release to install when no local APK is present in apks/. Releases\n# publish a VERSIONED asset (e.g. immortal-1.42.apk), so instead of hardcoding a\n# filename that 404s on the next release, the provisioner asks GitHub for the\n# latest release's .apk asset on RELEASE_REPO. Set RELEASE_APK_URL to a direct\n# URL only if you want to pin a specific build (it overrides RELEASE_REPO).\nRELEASE_REPO=starbrightlab/immortal\nRELEASE_APK_URL=\n\n# Shizuku - a privileged broker started once over ADB. We install + start it on\n# EVERY Portal now: it's broadly useful (Aurora Store's silent installs; the future\n# on-device Alexa-restore path that needs the privileged grants) and harmless where\n# unused. The Gen-1 Portal+ (Android 9) especially needs it because its stock\n# installer dialog is broken - Aurora's Session/Native installers can't get past it,\n# but its *Shizuku* installer can. Like our own daemon, the server must be restarted\n# after a reboot - the kit does that on its next run, or `./provision.sh --shizuku`.\n# For Aurora the user still flips two switches once (Settings -> Installation ->\n# Installation method -> Shizuku, then \"Allow\"); those live in Aurora's private\n# settings and can't be pre-set from here.\n# Set blank to skip installing Shizuku entirely. Latest: https://github.com/RikkaApps/Shizuku/releases\nSHIZUKU_APK_URL=\"https://github.com/RikkaApps/Shizuku/releases/download/v13.6.0/shizuku-v13.6.0.r1086.2650830c-release.apk\"\n\n# ---- Restore the original Amazon Alexa app (the \"hey\" free tier) -------------\n# Optional. Revives the discontinued on-device Alexa client (\"falcon\") so the\n# Portal does hands-free \"Hey Alexa\" again (text + voice + visual). We never host\n# Amazon's binary: the user downloads the PUBLIC stock APK from a firmware dump,\n# and we ship only a BINARY DIFF that reconstructs our patched+signed build\n# byte-for-byte. Run inline (you're asked y/N during provisioning) or standalone\n# with `./provision.sh --alexa`. NEVER uninstalls falcon (that would register a\n# new ghost device with Amazon); --restore removes only the wake-word app.\n#\n# RESTORE_ALEXA: blank = ask when interactive (skip in CI); true/false = force.\nRESTORE_ALEXA=\nFALCON_PKG=com.amazon.alexa.multimodal.falcon\n# PRIMARY source: the patched falcon APK, hosted directly. A single cross-platform download -\n# no bspatch (Windows has none), no flaky firmware-dump fetch, no stock+diff checksum drift.\n# This is what nearly everyone uses. (If this is ever taken down, blank it and the reconstruct\n# fallback below kicks back in.)\nFALCON_PATCHED_URL=\"https://github.com/starbrightlab/hey-dist/releases/download/v0.1.0/falcon.apk\"\n# FALLBACK only (used when FALCON_PATCHED_URL is blank): reconstruct the same APK from the public\n# Portal firmware dump (tadiphone) + our binary diff. Needs bspatch - macOS/Linux only.\nFALCON_STOCK_URL=\"https://dumps.tadiphone.dev/dumps/facebook/aloha/-/raw/aloha_prod-user-9-PKQ1.191202.001-1041481900013050-prod-keys/system/system/app/amazon_alexa/amazon_alexa.apk\"\nFALCON_STOCK_SHA256=d8f9e0aeec3f1d0a9e132643fc6d4fbbaf4e11e9955dc1bbcd6c1c4e3833e9db\nFALCON_BSDIFF_URL=\"https://github.com/starbrightlab/hey-dist/releases/download/v0.1.0/falcon.bsdiff\"\n# drop-5 build (5 dee.app-shared <permission> drops) - the A9-validated canonical that the\n# hosted falcon.bsdiff actually reconstructs. (drop-7 added EXTENSION/SKILL drops for the A10\n# Portal Go's newer dee.app, but A10 isn't supported yet + drop-7 was never re-validated on A9.)\nFALCON_RESULT_SHA256=76133f807e492e46aaf58e6ae503e623a93af840eaa3eccfb8630f1ecab3268d\n# The \"hey\" wake-word app (free build).\nMILLENNIUM_PKG=com.millennium\nMILLENNIUM_APK_URL=\"https://github.com/starbrightlab/hey-dist/releases/download/v0.1.0/millennium.apk\"\n# Local-path overrides for testing before the hosted URLs exist (any that are set\n# and exist are used instead of downloading):\n#   FALCON_PATCHED_LOCAL  pre-built patched+signed falcon APK (skips stock+bspatch)\n#   FALCON_STOCK_LOCAL    stock falcon APK (skips the ~120 MB download)\n#   FALCON_BSDIFF_LOCAL   our falcon.bsdiff\n#   MILLENNIUM_APK_LOCAL  the millennium APK\nFALCON_PATCHED_LOCAL=\nFALCON_STOCK_LOCAL=\nFALCON_BSDIFF_LOCAL=\nMILLENNIUM_APK_LOCAL=\n# WINDOWS ONLY: macOS/Linux have bspatch; Windows ships none. Point this at a\n# bspatch.exe to enable the reconstruct path on Windows, or set FALCON_PATCHED_LOCAL\n# instead. Ignored by the bash script (it finds bspatch on PATH). Blank = the\n# Windows -Alexa step skips falcon reconstruction with guidance.\nBSPATCH_EXE=\n";
